  const {rates}=useCourtPricing()
  return <main>
    <section className="hero"><div className="hero-copy"><span className="eyebrow"><span className="live-dot" /> OPEN DAILY · 6 AM — 11 PM</span><h1>Good games.<br /><em>Great people.</em></h1><p className="hero-sub">Your neighborhood pickleball spot for easy rallies, new friends, and a little friendly competition.</p><div className="hero-actions"><BookLink className="button button-lime" to="/book">Find your court <ArrowRight size={17} /></BookLink><a className="text-link" href="#courts">Explore the club <ArrowRight size={16} /></a></div><div className="hero-note"><div className="avatar-stack"><span>J</span><span>M</span><span>A</span><span>+</span></div><span><b>Your court is waiting.</b><br />Make today a little more active.</span></div></div><div className="hero-art"><div className="hero-glow" /><div className="court-graphic"><div className="court-label">STAG BASE PICKLE HUB</div><div className="court-boundary"><div className="court-center"/><div className="court-net"/><div className="kitchen left"/><div className="kitchen right"/><span className="court-number">01</span><span className="court-number right-number">02</span><div className="ball"><span /></div></div><div className="court-caption"><span><b>Play your way.</b> <span className="muted">Stay for one more.</span></span><span className="caption-arrow"><ArrowUpRight size={19}/></span></div></div><span className="art-tag tag-one"><Sparkles size={14}/> ALL LEVELS WELCOME</span><span className="art-tag tag-two"><span className="live-dot"/> GOOD ENERGY ONLY</span></div><div className="hero-bottom"><span>01 / 02 COURTS</span><span className="bottom-rule"/><span>SWIPE INTO A BETTER DAY</span><ArrowRight size={15}/></div></section>
    <section className="info-strip"><div><span className="strip-icon"><Clock3 /></span><span><small>EVERY DAY</small><b>6:00 AM – 11:00 PM</b></span></div><div><span className="strip-icon"><CreditCard /></span><span><small>COURT PRICING</small><b>₱{Math.min(rates[1],rates[2])}–₱{Math.max(rates[1],rates[2])} <i>/ court / hour</i></b></span></div><div><span className="strip-icon"><UserRound /></span><span><small>BRING YOUR CREW</small><b>All skill levels welcome</b></span></div><div className="strip-cta"><Link to="/courts">See the courts <ArrowRight size={16}/></Link></div></section>
    <section className="section courts-section" id="courts"><div className="section-heading"><div><span className="eyebrow">YOUR NEXT FAVORITE PLACE</span><h2>Pick your court.<br /><em>Bring your people.</em></h2></div><p>Two courts, one good time. Book by the hour and show up ready to play.</p></div><div className="court-cards"><CourtCard number="01" name="The Basic" kind="Court 1" color="court-green" floor="Rubberized"/><CourtCard number="02" name="The Pro" kind="Court 2" color="court-yellow" floor="Silica"/></div></section>
    <section id="how-it-works" className="how-section"><div className="how-title"><span className="eyebrow">NO FUSS. JUST FUN.</span><h2>Three steps to<br />your <em>next rally.</em></h2><p>Less planning. More playing. We’ll have the court ready.</p><BookLink className="button button-lime" to="/book">Let’s book it <ArrowRight size={16}/></BookLink></div><div className="steps"><Step n="01" icon={<CalendarDays/>} title="Choose your time" text="Pick a court, date, and start time that works for your crew."/><Step n="02" icon={<CreditCard/>} title="Payment is optional" text="Wait for admin confirmation. We will email GCash details so you can pay later."/><Step n="03" icon={<Trophy/>} title="Show up & play" text="Your booking is confirmed by admin. Pay by GCash later and enjoy your game."/></div></section>
    <section className="cta-band"><div><span className="eyebrow">YOUR PEOPLE ARE WAITING</span><h2>One more game?</h2><p>Make space for a little more fun this week.</p></div><BookLink className="button button-lime" to="/book">Book your court <ArrowRight size={17}/></BookLink><span className="cta-orb"/></section>
    <section className="landing-social-links" aria-label="Find and follow Stag Base"><a className="button button-dark" href="https://maps.app.goo.gl/FECaCqWTpP8kEeLb6" target="_blank" rel="noopener noreferrer"><MapPin size={16}/> Google Maps location <ArrowUpRight size={15}/></a><a className="button button-outline" href="https://www.facebook.com/profile.php?id=61591605945094" target="_blank" rel="noopener noreferrer"><Facebook size={16}/> Facebook profile <ArrowUpRight size={15}/></a></section>
  </main>
